package Day3;

public class Relational_Operator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
int a=20, b=10;
System.out.println(a<b);
System.out.println(a>b);
System.out.println(a<=b);
System.out.println(a>=b);
System.out.println(a!=b);
System.out.println(a==b);
boolean res = a>b;
System.out.println(res);
	}

}
